import type { Metadata } from "next";
import { siteConfig } from "@/config/site";

interface SeoOptions {
  title: string;
  description: string;
  /** Path of the page, e.g. "/products". Used for the canonical URL and og:url. */
  path: string;
  /** When true the title is used as-is (no " | Site name" suffix is added). */
  absoluteTitle?: boolean;
  image?: { url: string; width: number; height: number; alt: string };
}

/** Default social image (generated by src/app/opengraph-image.tsx) for pages without their own photo. */
const defaultImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${siteConfig.name} – ${siteConfig.tagline}`,
};

/** One place that builds title, description, canonical, Open Graph and Twitter tags for a page. */
export function buildMetadata({ title, description, path, absoluteTitle, image = defaultImage }: SeoOptions): Metadata {
  const fullTitle = absoluteTitle ? title : `${title} | ${siteConfig.name}`;
  return {
    title: absoluteTitle ? { absolute: fullTitle } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: siteConfig.name,
      locale: siteConfig.locale.replace("-", "_"),
      title: fullTitle,
      description,
      url: path,
      images: [image],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [image.url],
    },
  };
}
